mapper.select:
select count(*) from appointment
where patient_id = #{patientId}
  and status != 'CANCELLED'
  and appointment_time >= #{dayStart}
  and appointment_time < #{dayEnd}

select count(*) from appointment
where patient_id = #{patientId}
  and schedule_id = #{scheduleId}
  and status != 'CANCELLED'

SELECT count(*) FROM appointment a
LEFT JOIN doctor d ON a.doctor_id = d.id
LEFT JOIN clinic c ON d.clinic_id = c.id
WHERE a.status = #{status}

    AND c.department_id = #{departmentId}


    AND a.appointment_time >= #{startDate}


    AND a.appointment_time <= #{endDate}

SELECT count(*) FROM appointment a
LEFT JOIN doctor d ON a.doctor_id = d.id
LEFT JOIN clinic c ON d.clinic_id = c.id


        c.department_id = #{departmentId}


        AND a.appointment_time >= #{startDate}


        AND a.appointment_time <= #{endDate}

SELECT d.id AS doctorId, d.name AS doctorName, d.title AS doctorTitle, dept.id AS departmentId, dept.name AS departmentName, COUNT(DISTINCT DATE(s.schedule_date)) AS workDays, COUNT(a.id) AS totalCount, SUM(CASE WHEN a.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedCount, SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelledCount, SUM(CASE WHEN a.status = 'NO_SHOW' THEN 1 ELSE 0 END) AS noShowCount, SUM(a.actual_fee) AS totalRevenue FROM appointment a LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id LEFT JOIN schedule s ON a.schedule_id = s.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND d.id = #{doctorId}
GROUP BY d.id, d.name, d.title, dept.id, dept.name ORDER BY totalCount DESC

SELECT DATE(a.appointment_time) AS date, COUNT(*) AS appointmentCount, SUM(a.fee) AS originalFee, SUM(a.actual_fee) AS totalRevenue, SUM(a.actual_fee) AS actualFee FROM appointment a LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) AND a.status != 'CANCELLED'
AND dept.id = #{departmentId}
GROUP BY DATE(a.appointment_time) ORDER BY date

SELECT s.slot_type AS slotType, COUNT(a.id) AS appointmentCount, SUM(CASE WHEN a.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedCount, SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelledCount, SUM(a.actual_fee) AS totalRevenue FROM appointment a LEFT JOIN schedule s ON a.schedule_id = s.id LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND c.department_id = #{departmentId}
GROUP BY s.slot_type ORDER BY appointmentCount DESC

SELECT s.time_slot AS timeSlot, COUNT(a.id) AS appointmentCount, SUM(CASE WHEN a.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedCount, SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelledCount, SUM(a.actual_fee) AS totalRevenue FROM appointment a LEFT JOIN schedule s ON a.schedule_id = s.id LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND c.department_id = #{departmentId}
GROUP BY s.time_slot ORDER BY appointmentCount DESC

SELECT d.id AS doctorId, d.name AS doctorName, d.title AS doctorTitle, dept.id AS departmentId, dept.name AS departmentName, COUNT(a.id) AS totalCount, SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelledCount, CASE WHEN COUNT(a.id) > 0 THEN ROUND(SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) * 100.0 / COUNT(a.id), 2) ELSE 0 END AS cancellationRate FROM appointment a LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND d.id = #{doctorId}
GROUP BY d.id, d.name, d.title, dept.id, dept.name HAVING totalCount > 0 ORDER BY cancellationRate DESC

SELECT DATE(a.appointment_time) AS date, COUNT(*) AS totalCount, SUM(CASE WHEN a.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedCount, SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelledCount, SUM(CASE WHEN a.status = 'NO_SHOW' THEN 1 ELSE 0 END) AS noShowCount, SUM(CASE WHEN a.status = 'SCHEDULED' THEN 1 ELSE 0 END) AS scheduledCount, CASE WHEN COUNT(*) > 0 THEN ROUND(SUM(CASE WHEN a.status = 'CANCELLED' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) ELSE 0 END AS cancellationRate, SUM(a.actual_fee) AS totalRevenue FROM appointment a LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND dept.id = #{departmentId}
GROUP BY DATE(a.appointment_time) ORDER BY date

SELECT a.id AS appointmentId, p.name AS patientName, p.phone_number AS patientPhone, dept.name AS departmentName, d.name AS doctorName, s.slot_type AS slotType, DATE(s.schedule_date) AS appointmentDate, s.time_slot AS timeSlot, a.status AS status, a.fee AS registrationFee, a.actual_fee AS actualFee, a.appointment_time AS appointmentTime, a.source_type AS sourceType FROM appointment a LEFT JOIN patient p ON a.patient_id = p.id LEFT JOIN doctor d ON a.doctor_id = d.id LEFT JOIN clinic c ON d.clinic_id = c.id LEFT JOIN department dept ON c.department_id = dept.id LEFT JOIN schedule s ON a.schedule_id = s.id WHERE a.appointment_time >= #{startDate} AND a.appointment_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND dept.id = #{departmentId}
ORDER BY a.appointment_time DESC
